def kmeans_centers(points, n_clusters):
    if not points:
        raise ValueError("points must be non-empty")
    if not isinstance(n_clusters, int) or n_clusters <= 0:
        raise ValueError("n_clusters must be a positive integer")
    if n_clusters > len(points):
        raise ValueError("n_clusters cannot exceed the number of points")

    pts = sorted((float(x), float(y)) for x, y in points)
    n = len(pts)
    k = n_clusters

    if k == n:
        return [[x, y] for x, y in pts]

    def dist2(p, c):
        dx = p[0] - c[0]
        dy = p[1] - c[1]
        return dx * dx + dy * dy

    # Deterministic farthest-first initialization
    centers = [pts[0]]
    while len(centers) < k:
        best_idx = 0
        best_dist = -1.0

        for i, p in enumerate(pts):
            d = min(dist2(p, c) for c in centers)
            if d > best_dist:
                best_dist = d
                best_idx = i

        if best_dist <= 0.0:
            centers.append(pts[len(centers) % n])
        else:
            centers.append(pts[best_idx])

    # Lloyd's algorithm
    for _ in range(1000):
        clusters = [[] for _ in range(k)]

        for p in pts:
            best_j = 0
            best_d = dist2(p, centers[0])

            for j in range(1, k):
                d = dist2(p, centers[j])
                if d < best_d:
                    best_d = d
                    best_j = j

            clusters[best_j].append(p)

        new_centers = []
        for j, cluster in enumerate(clusters):
            if cluster:
                sx = sum(p[0] for p in cluster)
                sy = sum(p[1] for p in cluster)
                new_centers.append((sx / len(cluster), sy / len(cluster)))
            else:
                new_centers.append(centers[j])

        converged = all(
            abs(new_centers[i][0] - centers[i][0]) < 1e-9
            and abs(new_centers[i][1] - centers[i][1]) < 1e-9
            for i in range(k)
        )

        centers = new_centers
        if converged:
            break

    result = [[float(x), float(y)] for x, y in centers]
    result.sort(key=lambda p: (p[0], p[1]))
    return result
