from collections import Counter
from math import sqrt

def letter_count_correlations(strings):
    if not strings:
        return None

    counters = [Counter(s) for s in strings]
    letters = sorted({ch for counter in counters for ch in counter})
    n = len(strings)

    counts = {
        letter: [counter.get(letter, 0) for counter in counters]
        for letter in letters
    }

    means = {letter: sum(values) / n for letter, values in counts.items()}

    centered = {}
    norms = {}

    for letter, values in counts.items():
        centered_values = [value - means[letter] for value in values]
        centered[letter] = centered_values
        norms[letter] = sqrt(sum(value * value for value in centered_values))

    result = {}
    for x in letters:
        result[x] = {}
        for y in letters:
            numerator = sum(
                a * b for a, b in zip(centered[x], centered[y])
            )
            result[x][y] = numerator / (norms[x] * norms[y])

    return result
