def top_regression_residuals(data, feature, target, n=10):
    if feature not in data or target not in data:
        raise ValueError("feature and target must both be present in data")

    x = data[feature]
    y = data[target]

    m = len(x)
    if len(y) != m:
        raise ValueError("feature and target must have the same length")
    if m == 0:
        raise ValueError("cannot fit a regression on empty data")

    sum_x = sum(x)
    sum_y = sum(y)
    sum_xx = sum(xi * xi for xi in x)
    sum_xy = sum(xi * yi for xi, yi in zip(x, y))

    denominator = m * sum_xx - sum_x * sum_x

    if denominator == 0:
        slope = 0.0
        intercept = sum_y / m
    else:
        slope = (m * sum_xy - sum_x * sum_y) / denominator
        intercept = (sum_y - slope * sum_x) / m

    residuals = [
        abs(yi - (slope * xi + intercept))
        for xi, yi in zip(x, y)
    ]

    order = sorted(range(m), key=lambda i: (-residuals[i], i))

    if n <= 0:
        count = 0
    else:
        count = min(n, m)

    return order[:count], slope, intercept
