import csv
from io import StringIO
from math import isfinite


def normalize_numeric_columns(csv_text):
    reader = csv.reader(StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("No numeric columns")

    rows = [row for row in reader if row != []]

    if not header or not rows:
        raise ValueError("No numeric columns")

    ncols = len(header)

    for row in rows:
        if len(row) != ncols:
            raise ValueError("CSV row has wrong number of fields")

    numeric_flags = []
    parsed_columns = []

    for j in range(ncols):
        raw_values = [row[j] for row in rows]

        try:
            numbers = [float(value) for value in raw_values]
            if all(isfinite(num) for num in numbers):
                numeric_flags.append(True)
                parsed_columns.append(numbers)
            else:
                numeric_flags.append(False)
                parsed_columns.append(None)
        except ValueError:
            numeric_flags.append(False)
            parsed_columns.append(None)

    if not any(numeric_flags):
        raise ValueError("No numeric columns")

    result = {}

    for j, column_name in enumerate(header):
        raw_values = [row[j] for row in rows]

        if numeric_flags[j]:
            numbers = parsed_columns[j]
            minimum = min(numbers)
            maximum = max(numbers)

            if minimum == maximum:
                result[column_name] = [0.0 for _ in numbers]
            else:
                result[column_name] = [
                    (value - minimum) / (maximum - minimum)
                    for value in numbers
                ]
        else:
            result[column_name] = raw_values

    return result
