import math

def five_column_correlation_matrix(array):
    rows = list(array)

    if not rows:
        raise ValueError("input must contain at least one row")

    for row in rows:
        if len(row) != 5:
            raise ValueError("each row must contain exactly 5 values")

    n = len(rows)
    columns = [[float(row[j]) for row in rows] for j in range(5)]

    means = [sum(col) / n for col in columns]
    centered = [
        [value - means[j] for value in columns[j]]
        for j in range(5)
    ]
    sum_squares = [
        sum(value * value for value in col)
        for col in centered
    ]

    result = [[0.0] * 5 for _ in range(5)]

    for i in range(5):
        result[i][i] = 1.0
        for j in range(i + 1, 5):
            if sum_squares[i] == 0.0 or sum_squares[j] == 0.0:
                correlation = 0.0
            else:
                numerator = sum(
                    a * b for a, b in zip(centered[i], centered[j])
                )
                denominator = math.sqrt(sum_squares[i] * sum_squares[j])
                correlation = numerator / denominator

            result[i][j] = correlation
            result[j][i] = correlation

    return result
