from html.parser import HTMLParser

_VOID_TAGS = {
    "area", "base", "br", "col", "embed", "hr", "img", "input",
    "link", "meta", "param", "source", "track", "wbr"
}

class _FirstTagTextParser(HTMLParser):
    def __init__(self, tag):
        super().__init__(convert_charrefs=True)
        self.tag = tag.lower()
        self.found = False
        self.done = False
        self.depth = 0
        self.parts = []

    def handle_starttag(self, tag, attrs):
        if self.done:
            return

        tag = tag.lower()

        if not self.found:
            if tag == self.tag:
                self.found = True
                if tag in _VOID_TAGS:
                    self.done = True
                else:
                    self.depth = 1
        else:
            if tag == self.tag:
                self.depth += 1

    def handle_startendtag(self, tag, attrs):
        if self.done:
            return

        tag = tag.lower()

        if not self.found and tag == self.tag:
            self.found = True
            self.done = True

    def handle_endtag(self, tag):
        if self.done or not self.found:
            return

        tag = tag.lower()

        if tag == self.tag:
            self.depth -= 1
            if self.depth <= 0:
                self.done = True

    def handle_data(self, data):
        if self.found and not self.done:
            self.parts.append(data)


def first_tag_text(html, tag):
    parser = _FirstTagTextParser(tag)
    parser.feed(html)
    parser.close()

    if not parser.found:
        return None

    text = "".join(parser.parts)
    return text if text != "" else None
```

