from statistics import mean, pstdev

def find_zscore_outliers(prices, z_threshold):
    if not prices:
        return []

    mu = mean(prices)
    sigma = pstdev(prices)  # population standard deviation

    if sigma == 0:
        return []

    outliers = []
    for index, price in enumerate(prices):
        z_score = (price - mu) / sigma
        if abs(z_score) > z_threshold:
            outliers.append((index, price, z_score))

    return outliers
