from html.parser import HTMLParser


def extract_article_info(html):
    class ArticleParser(HTMLParser):
        VOID_ELEMENTS = {
            "area", "base", "br", "col", "embed", "hr", "img", "input",
            "link", "meta", "param", "source", "track", "wbr", "command",
            "keygen"
        }
        FIELDS = ("title", "date", "author")

        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.containers = []
            self.open_containers = []
            self.div_stack = []

        def _get_classes(self, attrs):
            for name, value in attrs:
                if name == "class":
                    return (value or "").split()
            return []

        def _new_container(self):
            return {
                "title": {"found": False, "parts": [], "stack": []},
                "date": {"found": False, "parts": [], "stack": []},
                "author": {"found": False, "parts": [], "stack": []},
            }

        def _start(self, tag, attrs):
            classes = self._get_classes(attrs)

            for idx in self.open_containers:
                state = self.containers[idx]

                if tag not in self.VOID_ELEMENTS:
                    for field in self.FIELDS:
                        entry = state[field]
                        if entry["stack"]:
                            entry["stack"].append(tag)

                if tag == "h1" and not state["title"]["found"]:
                    state["title"]["found"] = True
                    state["title"]["parts"] = []
                    state["title"]["stack"] = [tag]

                if tag == "span":
                    if "date" in classes and not state["date"]["found"]:
                        state["date"]["found"] = True
                        state["date"]["parts"] = []
                        state["date"]["stack"] = [tag]

                    if "author" in classes and not state["author"]["found"]:
                        state["author"]["found"] = True
                        state["author"]["parts"] = []
                        state["author"]["stack"] = [tag]

            if tag == "div":
                container_idx = None
                if "container" in classes:
                    container_idx = len(self.containers)
                    self.containers.append(self._new_container())
                    self.open_containers.append(container_idx)
                self.div_stack.append(container_idx)

        def _end(self, tag):
            for idx in self.open_containers:
                state = self.containers[idx]
                for field in self.FIELDS:
                    stack = state[field]["stack"]
                    if stack and stack[-1] == tag:
                        stack.pop()

            if tag == "div" and self.div_stack:
                idx = self.div_stack.pop()
                if idx is not None:
                    self.open_containers.remove(idx)

        def handle_starttag(self, tag, attrs):
            self._start(tag, attrs)

        def handle_startendtag(self, tag, attrs):
            self._start(tag, attrs)
            self._end(tag)

        def handle_endtag(self, tag):
            self._end(tag)

        def handle_data(self, data):
            for idx in self.open_containers:
                state = self.containers[idx]
                for field in self.FIELDS:
                    entry = state[field]
                    if entry["stack"]:
                        entry["parts"].append(data)

    parser = ArticleParser()
    parser.feed(html)
    parser.close()

    result = []
    for state in parser.containers:
        values = []
        for field, placeholder in (
            ("title", "No Title"),
            ("date", "No Date"),
            ("author", "No Author"),
        ):
            entry = state[field]
            if entry["found"]:
                values.append("".join(entry["parts"]).strip())
            else:
                values.append(placeholder)
        result.append(tuple(values))

    return result
