import numpy as np

def fit_and_score_linear_regression(train_X, train_y, test_X, test_y):
    if len(train_X) == 0:
        raise ValueError("training set is empty")
    if len(train_X) != len(train_y):
        raise ValueError("train_X and train_y have different lengths")
    if len(test_X) != len(test_y):
        raise ValueError("test_X and test_y have different lengths")
    if len(test_X) == 0:
        return float("nan")

    X_train = np.asarray(train_X, dtype=float)
    y_train = np.asarray(train_y, dtype=float)
    X_test = np.asarray(test_X, dtype=float)
    y_test = np.asarray(test_y, dtype=float)

    if X_train.ndim == 1:
        X_train = X_train.reshape(-1, 1)
    if X_test.ndim == 1:
        X_test = X_test.reshape(-1, 1)

    X_train_design = np.column_stack((np.ones(X_train.shape[0]), X_train))
    X_test_design = np.column_stack((np.ones(X_test.shape[0]), X_test))

    beta, *_ = np.linalg.lstsq(X_train_design, y_train, rcond=None)
    y_pred = X_test_design @ beta

    ss_res = np.sum((y_test - y_pred) ** 2)
    ss_tot = np.sum((y_test - np.mean(y_test)) ** 2)

    if ss_tot == 0:
        return 1.0 if ss_res == 0 else 0.0

    return float(1.0 - ss_res / ss_tot)
