import json

def key_mean_median(json_text):
    records = json.loads(json_text)
    values = {}

    for record in records:
        for key, value in record.items():
            values.setdefault(key, [])
            if isinstance(value, (int, float)) and not isinstance(value, bool):
                values[key].append(value)

    result = {}

    for key, nums in values.items():
        if not nums:
            result[key] = {"mean": None, "median": None}
            continue

        nums_sorted = sorted(nums)
        n = len(nums_sorted)

        mean = sum(nums_sorted) / n

        mid = n // 2
        if n % 2 == 1:
            median = float(nums_sorted[mid])
        else:
            median = (nums_sorted[mid - 1] + nums_sorted[mid]) / 2.0

        result[key] = {
            "mean": float(mean),
            "median": median
        }

    return result
