import math


def merge_and_standardize(rows1, rows2):
    def feature_columns(rows):
        cols = []
        seen = set()
        for row in rows:
            for key in row:
                if key != "id" and key not in seen:
                    seen.add(key)
                    cols.append(key)
        return cols

    cols1 = feature_columns(rows1)
    cols2 = feature_columns(rows2)

    rows1_by_id = {row["id"]: row for row in rows1}
    rows2_by_id = {row["id"]: row for row in rows2}

    stats = {}
    for col in cols1:
        values = [
            row[col]
            for row in rows1
            if col in row and row[col] is not None
        ]

        if values:
            mean = sum(values) / len(values)
            variance = sum((v - mean) ** 2 for v in values) / len(values)
            std = math.sqrt(variance)
        else:
            mean = 0.0
            std = 0.0

        stats[col] = (mean, std)

    result = []

    for row_id in sorted(set(rows1_by_id) | set(rows2_by_id)):
        merged = {"id": row_id}

        row1 = rows1_by_id.get(row_id)
        for col in cols1:
            if row1 is None or col not in row1 or row1[col] is None:
                merged[col] = None
            else:
                mean, std = stats[col]
                merged[col] = 0.0 if std == 0 else (row1[col] - mean) / std

        row2 = rows2_by_id.get(row_id)
        for col in cols2:
            merged[col] = None if row2 is None or col not in row2 else row2[col]

        result.append(merged)

    return result
