def detect_iqr_outliers(reference, values):
    if not reference:
        return []

    def percentile(sorted_data, p):
        n = len(sorted_data)
        if n == 1:
            return float(sorted_data[0])

        position = (n - 1) * p
        lower_index = int(position)
        fraction = position - lower_index

        if lower_index >= n - 1:
            return float(sorted_data[-1])

        lower_value = sorted_data[lower_index]
        upper_value = sorted_data[lower_index + 1]

        return float(lower_value + fraction * (upper_value - lower_value))

    sorted_reference = sorted(reference)

    q1 = percentile(sorted_reference, 0.25)
    q3 = percentile(sorted_reference, 0.75)
    iqr = q3 - q1

    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr

    outliers = []

    for number in list(reference) + list(values):
        number = float(number)
        if number < lower_fence or number > upper_fence:
            outliers.append(number)

    return outliers
