def scale_table_columns(data):
    columns = list(data.keys())

    if not columns:
        return {}

    row_count = len(data[columns[0]])

    # Keep only rows with no None values in any column.
    filtered = {col: [] for col in columns}
    for i in range(row_count):
        if all(data[col][i] is not None for col in columns):
            for col in columns:
                filtered[col].append(data[col][i])

    scaled = {}
    for col, values in filtered.items():
        if not values:
            scaled[col] = []
            continue

        minimum = min(values)
        maximum = max(values)

        if minimum == maximum:
            scaled[col] = [0.0 for _ in values]
        else:
            scaled[col] = [
                (value - minimum) / (maximum - minimum)
                for value in values
            ]

    return scaled
