```python
def column_linear_regression(rows, columns, target):
    if not rows:
        raise ValueError("rows must not be empty")
    if target not in columns:
        raise ValueError("target must be one of the columns")

    target_idx = columns.index(target)
    feature_indices = [i for i in range(len(columns)) if i != target_idx]
    p = len(feature_indices)

    if p == 0:
        y_sum = sum(float(row[target_idx]) for row in rows)
        return [], y_sum / len(rows)

    size = p + 1
    xtx = [[0.0] * size for _ in range(size)]
    xty = [0.0] * size

    for row in rows:
        x = [1.0] + [float(row[i]) for i in feature_indices]
        y = float(row[target_idx])

        for i in range(size):
            xty[i] += x[i] * y
            for j in range(size):
                xtx[i][j] += x[i] * x[j]

    # Solve (X^T X) beta = X^T y with Gauss-Jordan elimination.
    aug = [xtx[i][:] + [xty[i]] for i in range(size)]
    row = 0
    pivot_cols = []

    for col in range(size):
        pivot = row
        for r in range(row + 1, size):
            if abs(aug[r][col]) > abs(aug[pivot][col]):
                pivot = r

        if abs(aug[pivot][col]) < 1e-12:
            continue

        if pivot != row:
            aug[row], aug[pivot] = aug[pivot], aug[row]

        pivot_value = aug[row][col]
        for c in range(col, size + 1):
            aug[row][c] /= pivot_value

        for r in range(size):
            if r == row:
                continue
            factor = aug[r][col]
            if abs(factor) < 1e-15:
                continue
            for c in range(col, size + 1):
                aug[r][c] -= factor * aug[row][c]

        pivot_cols.append(col)
        row += 1
        if row == size:
            break

    beta = [0.0] * size
    for i, col in enumerate(pivot_cols):
        beta[col] = aug[i][size]

    return beta[1:], beta[0]
