from datetime import datetime
from zoneinfo import ZoneInfo

def publication_hour_stats(articles, timezone):
    if not articles:
        raise ValueError("articles must not be empty")

    tz = ZoneInfo(timezone)
    stats = {}

    for article in articles:
        if not isinstance(article, dict) or "category" not in article or "published_time" not in article:
            raise ValueError("each article must contain 'category' and 'published_time'")

        category = article["category"]
        published_time = article["published_time"]

        if isinstance(published_time, str):
            # Support trailing 'Z' in Python versions before 3.11.
            if published_time.endswith("Z"):
                published_time = published_time[:-1] + "+00:00"
            dt = datetime.fromisoformat(published_time)
        else:
            dt = published_time

        local_hour = dt.astimezone(tz).hour

        if category not in stats:
            stats[category] = {
                "count": 0,
                "total": 0,
                "min": local_hour,
                "max": local_hour,
            }

        entry = stats[category]
        entry["count"] += 1
        entry["total"] += local_hour
        entry["min"] = min(entry["min"], local_hour)
        entry["max"] = max(entry["max"], local_hour)

    result = {}
    for category in sorted(stats):
        entry = stats[category]
        result[category] = {
            "count": entry["count"],
            "mean": entry["total"] / entry["count"],
            "min": entry["min"],
            "max": entry["max"],
        }

    return result
