from collections import Counter
import random


def cluster_unique_points(points, n_clusters):
    counts = Counter(points)
    duplicates = {p: c for p, c in counts.items() if c > 1}

    unique = sorted(counts)
    if not unique or n_clusters <= 0:
        return duplicates, []

    k = min(int(n_clusters), len(unique))

    if k == 1:
        return duplicates, [list(unique)]

    if k == len(unique):
        clusters = [[p] for p in unique]
        clusters.sort()
        return duplicates, clusters

    pts = [tuple(map(float, p)) for p in unique]
    dim = len(pts[0])

    def dist2(a, b):
        return sum((a[i] - b[i]) ** 2 for i in range(dim))

    # Deterministic k-means++ initialization
    rng = random.Random(0)
    centers = [pts[0]]

    for _ in range(1, k):
        d2 = [min(dist2(p, c) for c in centers) for p in pts]
        total = sum(d2)

        if total == 0:
            for p in pts:
                if p not in centers:
                    centers.append(p)
                    break
            continue

        r = rng.random() * total
        acc = 0.0
        chosen = None

        for p, d in zip(pts, d2):
            if d == 0:
                continue
            acc += d
            if acc >= r:
                chosen = p
                break

        if chosen is None:
            for p, d in zip(reversed(pts), reversed(d2)):
                if d > 0:
                    chosen = p
                    break

        centers.append(chosen)

    labels = None

    for _ in range(100):
        new_labels = []

        for p in pts:
            best_i = 0
            best_d = dist2(p, centers[0])

            for i in range(1, k):
                d = dist2(p, centers[i])
                if d < best_d:
                    best_d = d
                    best_i = i

            new_labels.append(best_i)

        if new_labels == labels:
            labels = new_labels
            break

        labels = new_labels
        sums = [[0.0] * dim for _ in range(k)]
        cnts = [0] * k

        for p, lab in zip(pts, labels):
            cnts[lab] += 1
            for j in range(dim):
                sums[lab][j] += p[j]

        for i in range(k):
            if cnts[i]:
                centers[i] = tuple(sums[i][j] / cnts[i] for j in range(dim))
            else:
                far_idx = max(
                    range(len(pts)),
                    key=lambda idx: dist2(pts[idx], centers[labels[idx]])
                )
                centers[i] = pts[far_idx]

    final_labels = []

    for p in pts:
        best_i = 0
        best_d = dist2(p, centers[0])

        for i in range(1, k):
            d = dist2(p, centers[i])
            if d < best_d:
                best_d = d
                best_i = i

        final_labels.append(best_i)

    clusters = []

    for i in range(k):
        cluster = [unique[j] for j, lab in enumerate(final_labels) if lab == i]
        if cluster:
            clusters.append(sorted(cluster))

    clusters.sort()
    return duplicates, clusters
