def column_correlations(data):
    columns = list(data)

    centered = {}
    variances = {}

    for col in columns:
        values = data[col]
        n = len(values)
        mean = sum(values) / n if n else 0.0
        diffs = [v - mean for v in values]
        centered[col] = diffs
        variances[col] = sum(d * d for d in diffs)

    result = {col: {} for col in columns}

    for x in columns:
        for y in columns:
            if x == y:
                result[x][y] = 1.0
                continue

            denominator = (variances[x] * variances[y]) ** 0.5

            if denominator == 0:
                result[x][y] = 0.0
            else:
                covariance = sum(
                    dx * dy
                    for dx, dy in zip(centered[x], centered[y])
                )
                result[x][y] = covariance / denominator

    return result
