import csv
import io
from typing import Any, Dict, List


def _is_numeric_string(value: str) -> bool:
    if value is None:
        return False
    value = value.strip()
    if not value:
        return False
    try:
        float(value)
        return True
    except ValueError:
        return False


def _parse_numeric(value: str) -> Any:
    value = value.strip()
    try:
        return int(value)
    except ValueError:
        return float(value)


def sort_csv_rows(
    csv_text: str, sort_by_column: str = "title"
) -> List[Dict[str, Any]]:
    reader = csv.DictReader(io.StringIO(csv_text), restval="")
    fieldnames = reader.fieldnames

    if not fieldnames:
        return []

    if sort_by_column not in fieldnames:
        raise KeyError(f"Unknown sort column: {sort_by_column!r}")

    rows = [
        {column: row.get(column, "") for column in fieldnames}
        for row in reader
    ]

    numeric_columns = set()
    for column in fieldnames:
        values = [row[column] for row in rows]
        if values and all(_is_numeric_string(value) for value in values):
            numeric_columns.add(column)

    for row in rows:
        for column in numeric_columns:
            row[column] = _parse_numeric(row[column])

    rows.sort(key=lambda row: row[sort_by_column])
    return rows
