import math


def normalized_cumulative_sums(data):
    if not data:
        raise ValueError("data is empty")

    # Validate numeric types first
    for values in data.values():
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError("column contains non-numeric values")

    # Validate NaN values
    for values in data.values():
        for value in values:
            if math.isnan(value):
                raise ValueError("data contains NaN")

    result = {}

    for column, values in data.items():
        cumulative = []
        running_sum = 0

        for value in values:
            running_sum += value
            cumulative.append(running_sum)

        if not cumulative:
            result[column] = []
            continue

        minimum = min(cumulative)
        maximum = max(cumulative)

        if minimum == maximum:
            result[column] = [0.0] * len(cumulative)
        else:
            span = maximum - minimum
            result[column] = [(value - minimum) / span for value in cumulative]

    return result
