import math
import statistics

def random_walk_stats(steps):
    if not steps:
        raise ValueError("steps must not be empty")

    positions = []
    total = 0
    for step in steps:
        total += step
        positions.append(total)

    n = len(positions)
    count = float(n)
    mean = sum(positions) / n

    if n > 1:
        std = statistics.stdev(positions)
    else:
        std = 0.0

    ordered = sorted(positions)

    def percentile(p):
        if n == 1:
            return float(ordered[0])

        rank = (n - 1) * (p / 100.0)
        lower = math.floor(rank)
        upper = math.ceil(rank)

        if lower == upper:
            return float(ordered[lower])

        weight = rank - lower
        return float(ordered[lower] + (ordered[upper] - ordered[lower]) * weight)

    return {
        'count': count,
        'mean': float(mean),
        'std': float(std),
        'min': float(ordered[0]),
        '5%': percentile(5),
        '25%': percentile(25),
        '50%': percentile(50),
        '75%': percentile(75),
        '95%': percentile(95),
        'max': float(ordered[-1]),
    }
