    for column_name, values in data.items():
        if not all(
            isinstance(value, (int, float)) and not isinstance(value, bool)
            for value in values
        ):
            continue

        running_sum = 0
        cumulative = []

        for value in values:
            running_sum += value
            cumulative.append(running_sum)

        result[column_name] = cumulative

    if not result:
        raise ValueError("table has no numeric columns")

    return result
