import re
import xml.etree.ElementTree as ET


def xml_to_dict(xml):
    try:
        if isinstance(xml, str):
            s = xml

            # ElementTree rejects Unicode strings with an encoding declaration,
            # so normalize the declaration and parse as UTF-8 bytes.
            if s.lstrip().startswith("<?xml"):
                start = s.find("<?xml")
                end = s.find("?>", start)
                if end != -1:
                    decl = s[start:end + 2]
                    decl = re.sub(
                        r'encoding\s*=\s*([\'"])[^\'"]*\1',
                        'encoding="utf-8"',
                        decl,
                        count=1,
                        flags=re.IGNORECASE,
                    )
                    s = s[:start] + decl + s[end + 2:]

            data = s.encode("utf-8")
        else:
            data = xml

        root = ET.fromstring(data)

    except (ET.ParseError, ValueError, UnicodeEncodeError) as exc:
        raise ValueError(f"Malformed XML: {exc}") from exc

    def to_value(elem):
        children = list(elem)

        # Collect direct text, including text after child elements.
        parts = []
        if elem.text:
            parts.append(elem.text)
        for child in children:
            if child.tail:
                parts.append(child.tail)

        text = "".join(parts).strip() or None

        # Leaf element: return its text or None.
        if not elem.attrib and not children:
            return text

        result = {f"@{key}": value for key, value in elem.attrib.items()}

        if text is not None:
            result["#text"] = text

        for child in children:
            tag = child.tag
            child_value = to_value(child)

            if tag in result:
                if isinstance(result[tag], list):
                    result[tag].append(child_value)
                else:
                    result[tag] = [result[tag], child_value]
            else:
                result[tag] = child_value

        return result

    return {root.tag: to_value(root)}
