def standardize_columns(rows, columns, features):
    if not rows:
        return []

    column_index = {name: i for i, name in enumerate(columns)}
    feature_indices = {column_index[name] for name in features}

    result = [[float(value) for value in row] for row in rows]
    n = len(rows)

    for index in feature_indices:
        values = [float(row[index]) for row in rows]
        mean = sum(values) / n
        variance = sum((value - mean) ** 2 for value in values) / n
        std = variance ** 0.5

        for row in result:
            if std == 0:
                row[index] = 0.0
            else:
                row[index] = (row[index] - mean) / std

    return result
