from math import sqrt
from numbers import Real


def row_averages_and_correlations(data):
    if not isinstance(data, list):
        raise ValueError("data must be a list of rows")

    if len(data) == 0:
        return [], []

    n_cols = None

    for row in data:
        if not isinstance(row, list):
            raise ValueError("each row must be a list")

        if n_cols is None:
            n_cols = len(row)
        elif len(row) != n_cols:
            raise ValueError("data must be rectangular")

        for value in row:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise ValueError("all table entries must be real numbers")

    if n_cols == 0:
        raise ValueError("rows must contain at least one number")

    n_rows = len(data)

    averages = [sum(row) / n_cols for row in data]

    col_means = [
        sum(data[r][c] for r in range(n_rows)) / n_rows
        for c in range(n_cols)
    ]

    variances = [
        sum((data[r][c] - col_means[c]) ** 2 for r in range(n_rows))
        for c in range(n_cols)
    ]

    corr = [[0.0] * n_cols for _ in range(n_cols)]

    for i in range(n_cols):
        for j in range(n_cols):
            if i == j:
                corr[i][j] = 1.0
            else:
                denom = sqrt(variances[i]) * sqrt(variances[j])
                if denom == 0:
                    corr[i][j] = 0.0
                else:
                    numerator = sum(
                        (data[r][i] - col_means[i]) * (data[r][j] - col_means[j])
                        for r in range(n_rows)
                    )
                    corr[i][j] = numerator / denom

    return averages, corr
