import math


def standardized_tensor_product(P, T):
    if not P or not T:
        raise ValueError("P and T must be non-empty")

    k = len(P[0])
    if k != len(T):
        raise ValueError("P's number of columns must match T's first dimension")

    m = len(P)
    n = len(T[0]) if T else 0

    if n == 0:
        return []

    p = len(T[0][0])

    table = []
    for j in range(n):
        row = []
        for i in range(m):
            for ell in range(p):
                value = 0.0
                for a in range(k):
                    value += P[i][a] * T[a][j][ell]
                row.append(float(value))
        table.append(row)

    if not table:
        return table

    rows = len(table)
    cols = len(table[0])

    for c in range(cols):
        column = [table[r][c] for r in range(rows)]

        if all(value == column[0] for value in column):
            for r in range(rows):
                table[r][c] = 0.0
            continue

        mean = sum(column) / rows
        variance = sum((value - mean) ** 2 for value in column) / rows

        if variance == 0.0:
            for r in range(rows):
                table[r][c] = 0.0
        else:
            std_dev = math.sqrt(variance)
            for r in range(rows):
                table[r][c] = (column[r] - mean) / std_dev

    return table
