import csv
from io import StringIO

def fill_missing_with_column_mean(csv_text):
    if csv_text == "":
        return {}

    reader = csv.reader(StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {}

    n = len(header)
    if n == 0:
        return {}

    columns = [[] for _ in range(n)]

    for row in reader:
        if len(row) < n:
            row = row + [""] * (n - len(row))
        for i in range(n):
            columns[i].append(row[i])

    result = {}

    for name, values in zip(header, columns):
        present = [v for v in values if v != ""]
        is_numeric = bool(present)
        numbers = []

        if is_numeric:
            for value in present:
                try:
                    numbers.append(float(value))
                except ValueError:
                    is_numeric = False
                    break

        if is_numeric:
            column_mean = sum(numbers) / len(numbers)
            result[name] = [
                float(value) if value != "" else column_mean
                for value in values
            ]
        else:
            result[name] = [
                value if value != "" else None
                for value in values
            ]

    return result
