def encode_and_standardize(data, replacements):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    result = {}

    for column, values in data.items():
        replaced = []
        for value in values:
            try:
                value = replacements.get(value, value)
            except TypeError:
                pass
            replaced.append(value)

        if any(isinstance(value, str) for value in replaced):
            categories = sorted(set(replaced))
            codes = {value: i for i, value in enumerate(categories)}
            numeric_values = [codes[value] for value in replaced]
        else:
            numeric_values = replaced

        n = len(numeric_values)
        mean = sum(numeric_values) / n
        variance = sum((value - mean) ** 2 for value in numeric_values) / (n - 1)
        std = variance ** 0.5

        result[column] = [(value - mean) / std for value in numeric_values]

    return result
