    if not isinstance(records, list) or any(not isinstance(record, dict) for record in records):
        raise ValueError("Input must be a list of dicts")

    result = {}
    n = len(records)

    for key in ("x", "y", "z"):
        if not any(key in record for record in records):
            result[key] = None
            continue

        values = [record[key] if key in record else 0 for record in records]
        total = sum(values)

        result[key] = {
            "mean": total / n,
            "sum": total,
            "max": max(values),
            "min": min(values),
            "std": pstdev(values),
        }

    return result
