        raise ValueError("table must be a non-empty dict")

    # Validate equal-length list columns
    lengths = set()
    for values in table.values():
        if not isinstance(values, list):
            raise ValueError("each column must be a list")
        lengths.add(len(values))
    if len(lengths) > 1:
        raise ValueError("all columns must have equal length")

    result = {}
    found_numeric = False

    for column, values in table.items():
        if values and all(isinstance(v, Real) and not isinstance(v, bool) for v in values):
            found_numeric = True
            low = min(values)
            high = max(values)
            counts = [0] * 10

            if low == high:
                counts[-1] = len(values)
            else:
                span = high - low
                for value in values:
                    if value == high:
                        idx = 9
                    else:
                        ratio = (value - low) / span
                        idx = int(ratio * 10 + 1e-12)

                        if idx < 0:
                            idx = 0
                        elif idx > 9:
                            idx = 9

                    counts[idx] += 1

            result[column] = counts

    if not found_numeric:
        raise ValueError("table has no numeric columns")

    return result
