def normalize_columns(data_dict, data_keys):
    normalized = {}

    for key in data_keys:
        if key not in data_dict:
            continue

        values = data_dict[key]

        if not values:
            normalized[key] = []
            continue

        minimum = min(values)
        maximum = max(values)

        if maximum == minimum:
            normalized[key] = [0.0 for _ in values]
        else:
            span = maximum - minimum
            normalized[key] = [
                (value - minimum) / float(span)
                for value in values
            ]

    if not normalized:
        raise ValueError("None of the requested columns were found")

    return normalized
