import json
import math

def boxplot_stats_at_path(json_data, key_path):
    try:
        current = json.loads(json_data)
    except (json.JSONDecodeError, TypeError):
        raise ValueError("Malformed JSON")

    for key in key_path:
        if not isinstance(current, dict) or key not in current:
            raise KeyError(key)
        current = current[key]

    if not isinstance(current, str):
        raise ValueError("Value at key path must be a string of comma-separated numbers")

    if current.strip() == "":
        raise ValueError("Data string is empty")

    values = []
    for part in current.split(","):
        part = part.strip()
        if part == "":
            raise ValueError("Data string contains an empty value")
        try:
            value = float(part)
        except ValueError:
            raise ValueError(f"Non-numeric value: {part!r}")

        if not math.isfinite(value):
            raise ValueError(f"Non-finite value: {part!r}")

        values.append(value)

    values.sort()

    def percentile(p):
        n = len(values)
        if n == 1:
            return float(values[0])

        position = (n - 1) * p
        lower = math.floor(position)
        upper = math.ceil(position)

        if lower == upper:
            return float(values[lower])

        fraction = position - lower
        return float(values[lower] + (values[upper] - values[lower]) * fraction)

    q1 = percentile(0.25)
    median = percentile(0.5)
    q3 = percentile(0.75)

    iqr = q3 - q1
    lower_fence = q1 - 1.5 * iqr
    upper_fence = q3 + 1.5 * iqr

    inliers = [v for v in values if lower_fence <= v <= upper_fence]
    outliers = [float(v) for v in values if v < lower_fence or v > upper_fence]

    return {
        "q1": q1,
        "median": median,
        "q3": q3,
        "whisker_low": float(min(inliers)),
        "whisker_high": float(max(inliers)),
        "outliers": outliers,
    }
