def holdout_r_squared(train_x, train_y, test_x, test_y):
    if len(train_x) != len(train_y) or len(test_x) != len(test_y):
        raise ValueError("x and y arrays must have matching lengths")
    if len(test_x) < 2:
        raise ValueError("test set must contain at least 2 points")
    if len(train_x) == 0:
        raise ValueError("training set must not be empty")

    n = len(train_x)
    train_mean_x = sum(train_x) / n
    train_mean_y = sum(train_y) / n

    sxx = sum((x - train_mean_x) ** 2 for x in train_x)

    if sxx == 0:
        slope = 0.0
        intercept = train_mean_y
    else:
        sxy = sum(
            (x - train_mean_x) * (y - train_mean_y)
            for x, y in zip(train_x, train_y)
        )
        slope = sxy / sxx
        intercept = train_mean_y - slope * train_mean_x

    test_mean_y = sum(test_y) / len(test_y)

    ss_tot = sum((y - test_mean_y) ** 2 for y in test_y)
    ss_res = sum(
        (y - (slope * x + intercept)) ** 2
        for x, y in zip(test_x, test_y)
    )

    if ss_tot == 0:
        r_squared = 1.0 if ss_res == 0 else 0.0
    else:
        r_squared = 1.0 - ss_res / ss_tot

    return r_squared, slope, intercept
