import xml.etree.ElementTree as ET


def xml_to_dict(s):
    if not isinstance(s, str) or not s.strip():
        raise ValueError("XML input is empty or whitespace-only")

    def convert(elem):
        attrs = {"@" + key: value for key, value in elem.attrib.items()}
        children = list(elem)

        # Element with only text, or empty element
        if not attrs and not children:
            if elem.text is None:
                return None
            text = elem.text.strip()
            return text if text else None

        result = dict(attrs)

        # Add child elements, converting repeated sibling tags into lists
        for child in children:
            value = convert(child)
            tag = child.tag

            if tag in result:
                existing = result[tag]
                if isinstance(existing, list):
                    existing.append(value)
                else:
                    result[tag] = [existing, value]
            else:
                result[tag] = value

        # Collect text directly contained by this element
        text_parts = []
        if elem.text is not None:
            text_parts.append(elem.text)

        for child in children:
            if child.tail is not None:
                text_parts.append(child.tail)

        text = "".join(text_parts).strip()
        if text:
            result["#text"] = text

        return result

    root = ET.fromstring(s)
    return {root.tag: convert(root)}
