import re

def word_count_matrix(texts, stopwords):
    stopwords = {w.lower() for w in stopwords}

    tokenized = []
    vocab_set = set()

    for text in texts:
        words = [
            word for word in re.findall(r"[a-z]+", text.lower())
            if len(word) > 1 and word not in stopwords
        ]
        tokenized.append(words)
        vocab_set.update(words)

    vocab = sorted(vocab_set)
    word_to_index = {word: i for i, word in enumerate(vocab)}

    counts = []
    for words in tokenized:
        row = [0] * len(vocab)
        for word in words:
            row[word_to_index[word]] += 1
        counts.append(row)

    return vocab, counts
