def dbscan_cluster_labels(points):
    eps = 3
    min_samples = 2
    eps_sq = eps * eps

    n = len(points)
    if n == 0:
        return []

    def distance_sq(i, j):
        total = 0
        for a, b in zip(points[i], points[j]):
            d = a - b
            total += d * d
        return total

    # Precompute each point's eps-neighbourhood, including itself.
    neighbours = []
    for i in range(n):
        nbrs = []
        for j in range(n):
            if distance_sq(i, j) <= eps_sq:
                nbrs.append(j)
        neighbours.append(nbrs)

    labels = [-1] * n
    visited = [False] * n
    cluster_id = 0

    for i in range(n):
        if visited[i]:
            continue

        visited[i] = True
        nbrs = neighbours[i]

        if len(nbrs) < min_samples:
            labels[i] = -1
            continue

        labels[i] = cluster_id
        queue = list(nbrs)
        queued = set(nbrs)
        index = 0

        while index < len(queue):
            j = queue[index]
            index += 1

            if not visited[j]:
                visited[j] = True
                j_nbrs = neighbours[j]

                if len(j_nbrs) >= min_samples:
                    for nb in j_nbrs:
                        if nb not in queued:
                            queued.add(nb)
                            queue.append(nb)

            if labels[j] == -1:
                labels[j] = cluster_id

        cluster_id += 1

    return labels
