from html.parser import HTMLParser

def html_table_records(html, table_id):
    class TableParser(HTMLParser):
        def __init__(self):
            super().__init__(convert_charrefs=True)
            self.found = False
            self.active = False
            self.done = False
            self.table_depth = 0

            self.rows = []
            self.current_row = None
            self.current_cell = None
            self.cell_parts = []

        def _finish_cell(self):
            if self.current_cell is not None:
                text = "".join(self.cell_parts).strip()
                if self.current_row is not None:
                    self.current_row.append(text)
                self.current_cell = None
                self.cell_parts = []

        def _finish_row(self):
            if self.current_cell is not None:
                self._finish_cell()
            if self.current_row is not None:
                self.rows.append(self.current_row)
                self.current_row = None

        def handle_starttag(self, tag, attrs):
            if self.done:
                return

            tag = tag.lower()

            if tag == "table":
                if self.active:
                    self.table_depth += 1
                elif not self.found:
                    for name, value in attrs:
                        if name.lower() == "id" and value == table_id:
                            self.found = True
                            self.active = True
                            self.table_depth = 1
                            break
                return

            if not self.active:
                return

            if self.table_depth == 1:
                if tag == "tr":
                    if self.current_row is not None:
                        self._finish_row()
                    self.current_row = []

                elif tag in ("td", "th"):
                    if self.current_row is None:
                        self.current_row = []
                    if self.current_cell is not None:
                        self._finish_cell()
                    self.current_cell = tag
                    self.cell_parts = []

        def handle_startendtag(self, tag, attrs):
            self.handle_starttag(tag, attrs)
            self.handle_endtag(tag)

        def handle_endtag(self, tag):
            if self.done:
                return

            tag = tag.lower()

            if tag == "table":
                if self.active:
                    if self.table_depth == 1:
                        self._finish_row()
                        self.active = False
                        self.done = True
                    else:
                        self.table_depth -= 1
                return

            if not self.active:
                return

            if self.table_depth == 1:
                if tag in ("td", "th"):
                    self._finish_cell()
                elif tag == "tr":
                    self._finish_row()

        def handle_data(self, data):
            if self.active and self.current_cell is not None:
                self.cell_parts.append(data)

    parser = TableParser()
    parser.feed(html)
    parser.close()

    if not parser.found:
        raise ValueError(f"No table found with id {table_id!r}")

    rows = parser.rows
    if not rows:
        return []

    headers = rows[0]
    records = []

    for row in rows[1:]:
        record = {}
        for i, header in enumerate(headers):
            record[header] = row[i] if i < len(row) else ""
        records.append(record)

    return records
