import csv
import io
import re

_INT_RE = re.compile(r"[+-]?\d+\Z")
_FLOAT_RE = re.compile(r"[+-]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][+-]?\d+)?\Z")


def _try_parse_number(value):
    if not isinstance(value, str):
        return False, None

    text = value.strip()

    if _INT_RE.fullmatch(text):
        try:
            return True, int(text)
        except ValueError:
            return False, None

    if _FLOAT_RE.fullmatch(text):
        try:
            return True, float(text)
        except ValueError:
            return False, None

    return False, None


def concat_csv_tables(csv_texts):
    if not csv_texts:
        raise ValueError("csv_texts must not be empty")

    rows = []
    fieldnames = None

    for text in csv_texts:
        reader = csv.DictReader(io.StringIO(text))
        if fieldnames is None:
            fieldnames = reader.fieldnames or []
        rows.extend(reader)

    numeric_columns = set()

    for column in fieldnames:
        all_numeric = True
        has_value = False

        for row in rows:
            value = row.get(column)

            if value is None or value == "":
                all_numeric = False
                break

            is_number, _ = _try_parse_number(value)
            if not is_number:
                all_numeric = False
                break

            has_value = True

        if all_numeric and has_value:
            numeric_columns.add(column)

    result = []

    for row in rows:
        converted = {}

        for column in fieldnames:
            value = row.get(column, "")

            if column in numeric_columns:
                is_number, number = _try_parse_number(value)
                converted[column] = number if is_number else value
            else:
                converted[column] = value

        result.append(converted)

    return result
