import math

def mapped_correlation_matrix(data, mapping):
    if not isinstance(data, dict):
        raise ValueError("data must be a dict")

    mapped_data = {}
    for column, values in data.items():
        mapped_values = []
        for value in values:
            try:
                mapped_values.append(mapping[value])
            except (KeyError, TypeError):
                mapped_values.append(value)
        mapped_data[column] = mapped_values

    columns = list(mapped_data.keys())
    result = {column: {} for column in columns}

    if not columns:
        return result

    n = len(mapped_data[columns[0]])

    if n == 0:
        for a in columns:
            for b in columns:
                result[a][b] = 1.0 if a == b else float("nan")
        return result

    means = {
        column: sum(mapped_data[column]) / n
        for column in columns
    }

    centered = {
        column: [value - means[column] for value in mapped_data[column]]
        for column in columns
    }

    sum_squares = {
        column: sum(value * value for value in centered[column])
        for column in columns
    }

    for i, a in enumerate(columns):
        result[a][a] = 1.0

        for b in columns[i + 1:]:
            denominator = math.sqrt(sum_squares[a] * sum_squares[b])

            if denominator == 0:
                correlation = float("nan")
            else:
                numerator = sum(
                    x * y for x, y in zip(centered[a], centered[b])
                )
                correlation = numerator / denominator

            result[a][b] = correlation
            result[b][a] = correlation

    return result
