import math
import cmath
from statistics import median

def abs_sin_cos_spectrum_stats(range_start, range_end, step):
    if range_start > range_end:
        raise ValueError("range_start must not exceed range_end")
    if step <= 0:
        raise ValueError("step must be positive")

    samples = []
    x = range_start
    while x < range_end:
        samples.append(abs(math.sin(x) - math.cos(x)))
        x += step

    n = len(samples)
    if n == 0:
        raise ValueError("range contains no sample points")

    try:
        import numpy as np
        magnitudes = np.abs(np.fft.fft(np.asarray(samples, dtype=float)))
        return float(np.mean(magnitudes)), float(np.median(magnitudes))
    except ImportError:
        magnitudes = []
        for k in range(n):
            coeff = 0j
            for t, value in enumerate(samples):
                coeff += value * cmath.exp(-2j * math.pi * k * t / n)
            magnitudes.append(abs(coeff))

        return float(sum(magnitudes) / n), float(median(magnitudes))
