def csv_mean_median(csv_text):
    if not csv_text:
        return (None, None)

    values = []
    reader = csv.reader(io.StringIO(csv_text))
    header_skipped = False

    for row in reader:
        # Ignore blank rows
        if not row or all(cell.strip() == "" for cell in row):
            continue

        # Skip the first non-blank row as the header
        if not header_skipped:
            header_skipped = True
            continue

        value_text = row[0].strip()
        if not value_text:
            continue

        try:
            values.append(float(value_text))
        except ValueError:
            continue

    if not values:
        return (None, None)

    mean = sum(values) / len(values)
    values.sort()
    n = len(values)

    if n % 2 == 1:
        median = values[n // 2]
    else:
        median = (values[n // 2 - 1] + values[n // 2]) / 2.0

    return (float(mean), float(median))
