```python
from datetime import date, datetime
import calendar

_WEEKDAYS = {
    "MON": 0, "TUE": 1, "WED": 2, "THU": 3,
    "FRI": 4, "SAT": 5, "SUN": 6
}


def _parse_start_date(start_date):
    if not isinstance(start_date, str):
        raise ValueError(f"invalid start date: {start_date!r}")
    if len(start_date) != 10 or start_date[4] != "-" or start_date[7] != "-":
        raise ValueError(f"invalid start date: {start_date!r}")
    try:
        return datetime.strptime(start_date, "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"invalid start date: {start_date!r}") from None


def _last_day(year, month):
    return date(year, month, calendar.monthrange(year, month)[1])


def _next_month(year, month):
    if month == 12:
        return year + 1, 1
    return year, month + 1


def _month_end_dates(start):
    year, month = start.year, start.month
    current = _last_day(year, month)

    if current < start:
        year, month = _next_month(year, month)
        current = _last_day(year, month)

    while True:
        yield current
        year, month = _next_month(year, month)
        current = _last_day(year, month)


def _quarter_end_dates(start):
    year, month = start.year, start.month
    quarter_months = {3, 6, 9, 12}

    while month not in quarter_months or _last_day(year, month) < start:
        year, month = _next_month(year, month)

    current = _last_day(year, month)

    while True:
        yield current
        month += 3
        if month > 12:
            month -= 12
            year += 1
        current = _last_day(year, month)


def _nth_weekday(year, month, n, weekday):
    first = date(year, month, 1)
    offset = (weekday - first.weekday()) % 7
    day = 1 + offset + (n - 1) * 7
    return date(year, month, day)


def _nth_weekday_dates(start, n, weekday):
    year, month = start.year, start.month
    current = _nth_weekday(year, month, n, weekday)

    while current < start:
        year, month = _next_month(year, month)
        current = _nth_weekday(year, month, n, weekday)

    while True:
        yield current
        year, month = _next_month(year, month)
        current = _nth_weekday(year, month, n, weekday)


def forecast_schedule(start_date, freq, sales):
    start = _parse_start_date(start_date)

    if not isinstance(freq, str):
        raise ValueError("invalid freq")

    freq_clean = freq.strip()
    freq_lower = freq_clean.lower()

    if freq_lower == "month-end":
        dates = _month_end_dates(start)
    elif freq_lower == "quarter-end":
        dates = _quarter_end_dates(start)
    else:
        parts = freq_clean.upper().split("-")
        if len(parts) != 2:
            raise ValueError("invalid freq")

        try:
            n = int(parts[0])
        except ValueError:
            raise ValueError("invalid freq") from None

        weekday = parts[1].upper()

        if n < 1 or n > 4 or weekday not in _WEEKDAYS:
            raise ValueError("invalid freq")

        dates = _nth_weekday_dates(start, n, _WEEKDAYS[weekday])

    return [(next(dates).isoformat(), value) for value in sales]
