        if customer in seen:
            continue
        seen.add(customer)

        sales = row["Sales"]
        try:
            sales_value = int(sales)
        except ValueError:
            sales_value = float(sales)

        total_sales += sales_value
        category_counts[row["Category"]] += 1

    if category_counts:
        most_popular = min(
            category_counts,
            key=lambda category: (-category_counts[category], category)
        )
    else:
        most_popular = None

    return {
        "Total Sales": total_sales,
        "Most Popular Category": most_popular
    }
