from numbers import Real


def column_covariance(columns):
    if not columns:
        raise ValueError("table has no columns")

    names = list(columns)
    n = len(columns[names[0]])

    if n == 0:
        raise ValueError("table has no rows")
    if n < 2:
        raise ValueError("table must have at least two rows")

    for name in names:
        values = columns[name]

        if len(values) != n:
            raise ValueError("all columns must have the same length")

        for value in values:
            if isinstance(value, bool) or not isinstance(value, Real):
                raise TypeError(f"non-numeric value in column {name!r}")

    means = {
        name: sum(columns[name]) / n
        for name in names
    }

    result = {}
    for a in names:
        result[a] = {}
        a_values = columns[a]
        a_mean = means[a]

        for b in names:
            b_values = columns[b]
            b_mean = means[b]

            covariance = sum(
                (x - a_mean) * (y - b_mean)
                for x, y in zip(a_values, b_values)
            ) / (n - 1)

            result[a][b] = covariance

    return result
