import csv
import re
from io import StringIO

_INT_RE = re.compile(r"^[+-]?\d+$")
_NUMBER_RE = re.compile(
    r"^[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?$"
)


def _is_numeric(value: str) -> bool:
    return bool(_NUMBER_RE.fullmatch(value.strip()))


def _parse_number(value: str):
    value = value.strip()
    if _INT_RE.fullmatch(value):
        return int(value)
    return float(value)


def sort_csv_rows(csv_text, sort_key):
    reader = csv.reader(StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        raise ValueError("CSV must contain a header row")

    if sort_key not in header:
        raise ValueError(f"Column {sort_key!r} does not exist")

    rows = []
    for record in reader:
        if len(record) < len(header):
            record = record + [""] * (len(header) - len(record))
        elif len(record) > len(header):
            record = record[: len(header)]

        rows.append(dict(zip(header, record)))

    numeric_columns = set()
    for column in header:
        values = [row[column] for row in rows]
        if values and all(_is_numeric(value) for value in values):
            numeric_columns.add(column)

    for row in rows:
        for column in numeric_columns:
            row[column] = _parse_number(row[column])

    return sorted(rows, key=lambda row: row[sort_key])
