def standardize_columns(data):
    n = len(data)
    if n == 0:
        return []

    columns = len(data[0])
    if columns == 0:
        return [[] for _ in range(n)]

    means = [
        sum(row[j] for row in data) / n
        for j in range(columns)
    ]

    stds = []
    for j in range(columns):
        mean = means[j]
        variance = sum((row[j] - mean) ** 2 for row in data) / n
        stds.append(variance ** 0.5)

    result = []
    for row in data:
        standardized_row = []
        for j in range(columns):
            if stds[j] == 0:
                standardized_row.append(0.0)
            else:
                standardized_row.append((row[j] - means[j]) / stds[j])
        result.append(standardized_row)

    return result
