def standardize_with_row_means(data):
    if not data:
        return []

    n_rows = len(data)
    n_cols = len(data[0])

    column_means = [
        sum(data[i][j] for i in range(n_rows)) / n_rows
        for j in range(n_cols)
    ]

    column_stds = []
    for j in range(n_cols):
        variance = sum(
            (data[i][j] - column_means[j]) ** 2
            for i in range(n_rows)
        ) / n_rows
        column_stds.append(variance ** 0.5)

    result = []
    for row in data:
        standardized_row = []
        for j, value in enumerate(row):
            std = column_stds[j]
            if std == 0:
                standardized_row.append(0.0)
            else:
                standardized_row.append((value - column_means[j]) / std)

        row_mean = sum(standardized_row) / len(standardized_row) if standardized_row else 0.0
        result.append(standardized_row + [row_mean])

    return result
