def complete_row_histogram(data, bins):
    if bins <= 0:
        raise ValueError("bins must be a positive integer")

    columns = list(data)
    cleaned = {col: [] for col in columns}

    if not columns:
        return cleaned, None

    num_rows = len(data[columns[0]])

    for i in range(num_rows):
        if any(data[col][i] is None for col in columns):
            continue

        for col in columns:
            cleaned[col].append(float(data[col][i]))

    pooled = []
    for col in columns:
        pooled.extend(cleaned[col])

    if not pooled:
        return cleaned, None

    lo = min(pooled)
    hi = max(pooled)

    if lo == hi:
        return cleaned, None

    width = (hi - lo) / bins
    counts = [0] * bins

    for value in pooled:
        index = int((value - lo) / width)
        if index >= bins:
            index = bins - 1
        elif index < 0:
            index = 0
        counts[index] += 1

    return cleaned, counts
