```python
def cluster_labels(rows):
    if not rows:
        return []

    n = len(rows)
    m = len(rows[0])
    data = [[float(v) for v in row] for row in rows]

    # Standardize each column to zero mean and unit variance.
    means = [sum(data[i][j] for i in range(n)) / n for j in range(m)]
    scales = []
    for j in range(m):
        var = sum((data[i][j] - means[j]) ** 2 for i in range(n)) / n
        sd = var ** 0.5
        scales.append(sd if sd != 0 else 1.0)

    X = [
        [(data[i][j] - means[j]) / scales[j] for j in range(m)]
        for i in range(n)
    ]

    k = min(3, n)

    def dist2(a, b):
        return sum((a[j] - b[j]) ** 2 for j in range(m))

    # Deterministic farthest-first initialization.
    centroids = [X[0][:]]
    used = {0}

    while len(centroids) < k:
        best_i = -1
        best_d = -1.0

        for i, p in enumerate(X):
            if i in used:
                continue
            d = min(dist2(p, c) for c in centroids)
            if d > best_d:
                best_d = d
                best_i = i

        if best_i == -1:
            best_i = next(i for i in range(n) if i not in used)

        centroids.append(X[best_i][:])
        used.add(best_i)

    def assign(centroids):
        labels = []
        for p in X:
            best_c = 0
            best_d = dist2(p, centroids[0])

            for c in range(1, k):
                d = dist2(p, centroids[c])
                if d < best_d:
                    best_d = d
                    best_c = c

            labels.append(best_c)

        return labels

    def centroids_close(a, b):
        for va, vb in zip(a, b):
            for x, y in zip(va, vb):
                if abs(x - y) > 1e-12:
                    return False
        return True

    labels = assign(centroids)

    for _ in range(100):
        new_centroids = []

        for c in range(k):
            members = [X[i] for i, lab in enumerate(labels) if lab == c]

            if members:
                new_centroids.append([
                    sum(p[j] for p in members) / len(members)
                    for j in range(m)
                ])
            else:
                # Re-seed an empty cluster at the worst-fit point.
                candidate_i = 0
                candidate_d = -1.0

                for i, p in enumerate(X):
                    lab = labels[i]
                    d = dist2(p, centroids[lab])
                    if d > candidate_d:
                        candidate_d = d
                        candidate_i = i

                new_centroids.append(X[candidate_i][:])

        if centroids_close(new_centroids, centroids):
            centroids = new_centroids
            break

        centroids = new_centroids
        labels = assign(centroids)

    # Final assignment using converged centroids.
    labels = assign(centroids)

    # Renumber clusters by first appearance.
    mapping = {}
    result = []
    next_label = 0

    for lab in labels:
        if lab not in mapping:
            mapping[lab] = next_label
            next_label += 1
        result.append(mapping[lab])

    return result
