from datetime import datetime

def date_histogram(dates, date_format):
    if not dates:
        return [0] * 10

    parsed = [datetime.strptime(date, date_format) for date in dates]
    start = min(parsed)
    end = max(parsed)

    counts = [0] * 10

    if start == end:
        counts[9] = len(parsed)
        return counts

    span = end - start
    span_us = (span.days * 86400 + span.seconds) * 1_000_000 + span.microseconds

    for dt in parsed:
        if dt == end:
            index = 9
        else:
            delta = dt - start
            delta_us = (delta.days * 86400 + delta.seconds) * 1_000_000 + delta.microseconds
            index = (delta_us * 10) // span_us
            if index > 9:
                index = 9

        counts[index] += 1

    return counts
