def last_column_skewness(rows):
    if not rows or not rows[0]:
        raise ValueError("table must have at least one row and one column")

    values = [row[-1] for row in rows if row[-1] is not None]
    n = len(values)

    if n == 0:
        raise ValueError("last column has no non-missing values")

    mean = sum(values) / n
    m2 = sum((x - mean) ** 2 for x in values) / n
    m3 = sum((x - mean) ** 3 for x in values) / n

    if m2 == 0:
        return 0.0

    return m3 / (m2 ** 1.5)
