def fruit_sales_box_stats(records):
    if not records:
        raise ValueError("records must not be empty")

    grouped = {}
    for fruit, _day, sales in records:
        grouped.setdefault(fruit, []).append(sales)

    def quantile(values, p):
        pos = (len(values) - 1) * p
        lower = int(pos)
        upper = min(lower + 1, len(values) - 1)
        return float(
            values[lower] + (pos - lower) * (values[upper] - values[lower])
        )

    result = {}
    for fruit, sales in grouped.items():
        sales.sort()
        result[fruit] = (
            float(sales[0]),
            quantile(sales, 0.25),
            quantile(sales, 0.50),
            quantile(sales, 0.75),
            float(sales[-1]),
        )

    return result
