from html import unescape
from html.parser import HTMLParser


class _LinkParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=False)
        self.links = []
        self.active = []

    def _append_text(self, text):
        for link in self.active:
            link["parts"].append(text)

    def handle_data(self, data):
        if data:
            self._append_text(unescape(data))

    def handle_entityref(self, name):
        self._append_text(unescape(f"&{name};"))

    def handle_charref(self, name):
        self._append_text(unescape(f"&#{name};"))

    def handle_starttag(self, tag, attrs):
        if tag.lower() != "a":
            return

        href = None
        for name, value in attrs:
            if name.lower() == "href":
                href = "" if value is None else value
                break

        link = {"href": href, "parts": []}
        self.links.append(link)
        self.active.append(link)

    def handle_startendtag(self, tag, attrs):
        if tag.lower() != "a":
            return

        href = None
        for name, value in attrs:
            if name.lower() == "href":
                href = "" if value is None else value
                break

        self.links.append({"href": href, "parts": []})

    def handle_endtag(self, tag):
        if tag.lower() == "a" and self.active:
            self.active.pop()

    def result(self):
        return [
            ("".join(link["parts"]), link["href"])
            for link in self.links
        ]


def extract_links(html):
    parser = _LinkParser()
    parser.feed(html)
    parser.close()
    return parser.result()
