from math import sqrt

def row_zscores_and_correlation(data):
    z_scores = []

    for row in data:
        n = len(row)
        if n == 0:
            z_scores.append([])
            continue

        mean = sum(row) / n
        variance = sum((x - mean) ** 2 for x in row) / n
        std = sqrt(variance)

        if std == 0:
            z_scores.append([0.0] * n)
        else:
            z_scores.append([(x - mean) / std for x in row])

    if not z_scores or not z_scores[0]:
        return z_scores, []

    n_rows = len(z_scores)
    n_cols = len(z_scores[0])

    col_means = [
        sum(z_scores[r][c] for r in range(n_rows)) / n_rows
        for c in range(n_cols)
    ]

    centered_cols = []
    norms = []

    for c in range(n_cols):
        centered = [
            z_scores[r][c] - col_means[c]
            for r in range(n_rows)
        ]
        centered_cols.append(centered)
        norms.append(sqrt(sum(v * v for v in centered)))

    corr = [[0.0] * n_cols for _ in range(n_cols)]

    for i in range(n_cols):
        corr[i][i] = 1.0

        for j in range(i + 1, n_cols):
            if norms[i] == 0 or norms[j] == 0:
                value = 0.0
            else:
                numerator = sum(
                    centered_cols[i][k] * centered_cols[j][k]
                    for k in range(n_rows)
                )
                value = numerator / (norms[i] * norms[j])

                if value > 1.0:
                    value = 1.0
                elif value < -1.0:
                    value = -1.0

            corr[i][j] = value
            corr[j][i] = value

    return z_scores, corr
```

