def timestamp_dates_and_histogram(timestamps):
    if not timestamps:
        raise ValueError("timestamps must be a non-empty list")

    dates = []
    for ts in timestamps:
        dt = datetime.fromtimestamp(ts, tz=timezone.utc)
        dates.append(
            f"{dt.year:04d}-{dt.month:02d}-{dt.day:02d} "
            f"{dt.hour:02d}:{dt.minute:02d}:{dt.second:02d}"
        )

    min_ts = min(timestamps)
    max_ts = max(timestamps)
    span = max_ts - min_ts

    counts = [0] * 10

    if span == 0:
        counts[-1] = len(timestamps)
    else:
        for ts in timestamps:
            if ts == max_ts:
                index = 9
            else:
                index = int(((ts - min_ts) * 10) // span)
                if index < 0:
                    index = 0
                elif index > 9:
                    index = 9
            counts[index] += 1

    return dates, counts
