import math

def standardize_filtered(data, age, weight):
    if 'Age' not in data:
        raise KeyError('Age')
    if 'Weight' not in data:
        raise KeyError('Weight')

    ages = data['Age']
    weights = data['Weight']

    kept_rows = [
        i for i in range(len(ages))
        if ages[i] < age and weights[i] > weight
    ]

    result = {}

    for column, values in data.items():
        if not kept_rows:
            result[column] = []
            continue

        filtered = [values[i] for i in kept_rows]
        n = len(filtered)
        mean = sum(filtered) / n

        variance = sum((x - mean) ** 2 for x in filtered) / n

        if variance == 0:
            result[column] = [0.0 for _ in filtered]
        else:
            std = math.sqrt(variance)
            result[column] = [(x - mean) / std for x in filtered]

    return result
