def min_max_scale_columns(rows):
    if not rows:
        return []

    num_columns = len(rows[0])

    mins = [float("inf")] * num_columns
    maxs = [float("-inf")] * num_columns

    for row in rows:
        for j, value in enumerate(row):
            if value < mins[j]:
                mins[j] = value
            if value > maxs[j]:
                maxs[j] = value

    scaled = []
    for row in rows:
        new_row = []
        for j, value in enumerate(row):
            column_range = maxs[j] - mins[j]
            if column_range == 0:
                new_row.append(0.0)
            else:
                new_row.append((value - mins[j]) / column_range)
        scaled.append(new_row)

    return scaled
