def cluster_point_labels(data, n_clusters):
    if not data:
        raise ValueError("data must not be empty")
    if n_clusters <= 0:
        raise ValueError("n_clusters must be positive")

    points = [(float(x), float(y)) for _, x, y in data]
    n = len(points)

    # Use distinct coordinates so we don't try to create impossible empty clusters.
    unique_points = []
    seen = set()
    for p in points:
        if p not in seen:
            seen.add(p)
            unique_points.append(p)

    k = min(n_clusters, len(unique_points), n)
    if k == 1:
        return [0] * n

    def dist2(a, b):
        dx = a[0] - b[0]
        dy = a[1] - b[1]
        return dx * dx + dy * dy

    def run_kmeans(init_centroids):
        centroids = list(init_centroids)
        labels = [-1] * n

        for _ in range(100):
            new_labels = []
            for p in points:
                best_j = 0
                best_d = dist2(p, centroids[0])
                for j in range(1, k):
                    d = dist2(p, centroids[j])
                    if d < best_d:
                        best_d = d
                        best_j = j
                new_labels.append(best_j)

            sums = [[0.0, 0.0, 0] for _ in range(k)]
            for i, label in enumerate(new_labels):
                sums[label][0] += points[i][0]
                sums[label][1] += points[i][1]
                sums[label][2] += 1

            new_centroids = []
            empty = []
            for j in range(k):
                if sums[j][2] == 0:
                    empty.append(j)
                    new_centroids.append((0.0, 0.0))
                else:
                    new_centroids.append((
                        sums[j][0] / sums[j][2],
                        sums[j][1] / sums[j][2]
                    ))

            if empty:
                used = set()
                for e in empty:
                    best_i = -1
                    best_d = -1.0
                    for i, p in enumerate(points):
                        if i in used:
                            continue
                        d = dist2(p, centroids[new_labels[i]])
                        if d > best_d:
                            best_d = d
                            best_i = i
                    if best_i >= 0:
                        used.add(best_i)
                        new_centroids[e] = points[best_i]
                    else:
                        new_centroids[e] = centroids[e]

            if new_labels == labels and not empty:
                centroids = new_centroids
                labels = new_labels
                break

            labels = new_labels
            centroids = new_centroids

        inertia = sum(dist2(points[i], centroids[labels[i]]) for i in range(n))
        return labels, inertia

    def farthest_first(start):
        cents = [start]
        while len(cents) < k:
            best = None
            best_d = -1.0
            for p in unique_points:
                d = min(dist2(p, c) for c in cents)
                if d > best_d:
                    best_d = d
                    best = p
            if best is None:
                break
            cents.append(best)

        while len(cents) < k:
            cents.append(unique_points[len(cents) % len(unique_points)])

        return cents

    initializations = [unique_points[:k]]

    starts = [
        unique_points[0],
        unique_points[-1],
        unique_points[len(unique_points) // 2],
        min(unique_points, key=lambda p: p[0]),
        max(unique_points, key=lambda p: p[0]),
        min(unique_points, key=lambda p: p[1]),
        max(unique_points, key=lambda p: p[1]),
    ]

    mean_x = sum(p[0] for p in unique_points) / len(unique_points)
    mean_y = sum(p[1] for p in unique_points) / len(unique_points)
    starts.append(min(unique_points, key=lambda p: dist2(p, (mean_x, mean_y))))

    seen_starts = set()
    for start in starts:
        if start in seen_starts:
            continue
        seen_starts.add(start)
        initializations.append(farthest_first(start))

    best_labels = None
    best_inertia = float("inf")

    for init in initializations:
        if len(init) < k:
            continue
        labels, inertia = run_kmeans(init)
        if inertia < best_inertia - 1e-12:
            best_inertia = inertia
            best_labels = labels

    if best_labels is None:
        best_labels = [0] * n

    # Renumber clusters by first appearance in input order.
    mapping = {}
    result = []
    for label in best_labels:
        if label not in mapping:
            mapping[label] = len(mapping)
        result.append(mapping[label])

    return result
```

