from bisect import bisect_right

def histogram_bins(values, bins):
    vals = list(values)

    if isinstance(bins, int):
        if bins <= 0:
            raise ValueError("bins must be a positive integer")

        if not vals:
            edges = [0.0] * (bins + 1)
        else:
            lo = float(min(vals))
            hi = float(max(vals))

            if lo == hi:
                edges = [lo] * (bins + 1)
            else:
                step = (hi - lo) / bins
                edges = [lo + i * step for i in range(bins)]
                edges.append(hi)
    else:
        edges = [float(edge) for edge in bins]

    if len(edges) < 2:
        return [], edges

    counts = [0] * (len(edges) - 1)
    lo, hi = edges[0], edges[-1]

    for value in vals:
        if value < lo or value > hi:
            continue

        if value == hi:
            index = len(counts) - 1
        else:
            index = bisect_right(edges, value, 0, len(edges) - 1) - 1

        if 0 <= index < len(counts):
            counts[index] += 1

    return counts, edges
