import csv
import io
import math
import re

_NUMBER_RE = re.compile(
    r'^[+-]?(?:(?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?$'
)


def _parse_number(value):
    value = value.strip()
    if not value or not _NUMBER_RE.fullmatch(value):
        return None
    try:
        return float(value.replace(',', ''))
    except ValueError:
        return None


def summarize_numeric_csv(csv_text):
    reader = csv.reader(io.StringIO(csv_text))

    try:
        header = next(reader)
    except StopIteration:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    n_cols = len(header)
    values = [[] for _ in range(n_cols)]
    valid = [True] * n_cols
    row_count = 0

    for row in reader:
        if len(row) == 0:
            continue

        row_count += 1

        for i in range(n_cols):
            if not valid[i]:
                continue

            if i >= len(row):
                valid[i] = False
                continue

            number = _parse_number(row[i])
            if number is None:
                valid[i] = False
            else:
                values[i].append(number)

    if row_count == 0:
        return {'means': {}, 'std_devs': {}, 'f_value': None}

    means = {}
    std_devs = {}
    groups = []

    for i in range(n_cols):
        if valid[i] and values[i]:
            name = header[i]
            group = values[i]
            n = len(group)
            mean = sum(group) / n

            means[name] = mean
            groups.append(group)

            if n > 1:
                variance = sum((x - mean) ** 2 for x in group) / (n - 1)
                std_devs[name] = math.sqrt(variance)
            else:
                std_devs[name] = None

    f_value = None

    if len(groups) >= 2:
        total_n = sum(len(group) for group in groups)
        k = len(groups)

        if total_n > k:
            grand_mean = sum(sum(group) for group in groups) / total_n
            group_means = [sum(group) / len(group) for group in groups]

            ssb = sum(
                len(group) * (mean - grand_mean) ** 2
                for group, mean in zip(groups, group_means)
            )

            ssw = sum(
                sum((x - mean) ** 2 for x in group)
                for group, mean in zip(groups, group_means)
            )

            dfb = k - 1
            dfw = total_n - k

            msb = ssb / dfb
            msw = ssw / dfw

            if msw == 0:
                f_value = None if msb == 0 else float('inf')
            else:
                f_value = msb / msw

    return {
        'means': means,
        'std_devs': std_devs,
        'f_value': f_value,
    }
```

