import math

def standardize_columns(data):
    result = {}

    for name, values in data.items():
        n = len(values)

        if n == 0:
            result[name] = ([], [0] * 20)
            continue

        mean = sum(values) / n

        if min(values) == max(values):
            standardized = [0.0] * n
        else:
            variance = sum((x - mean) ** 2 for x in values) / n
            std = math.sqrt(variance)

            if std == 0:
                standardized = [0.0] * n
            else:
                standardized = [(x - mean) / std for x in values]

        counts = [0] * 20
        lo = min(standardized)
        hi = max(standardized)

        if lo == hi:
            counts[-1] = n
        else:
            width = (hi - lo) / 20.0

            for x in standardized:
                if x >= hi:
                    idx = 19
                else:
                    idx = int((x - lo) / width)
                    idx = max(0, min(19, idx))

                counts[idx] += 1

        result[name] = (standardized, counts)

    return result
