def temperature_month_day_grid(records):
    if not records:
        raise ValueError("records cannot be empty")

    required_keys = ("Date", "Time", "Temperature")

    for record in records:
        if not isinstance(record, dict) or not all(key in record for key in required_keys):
            raise ValueError("each record must contain Date, Time, and Temperature")

    months = sorted({
        int(record["Date"].split("-")[1])
        for record in records
    })
    days = sorted({
        int(record["Date"].split("-")[2])
        for record in records
    })

    month_index = {month: i for i, month in enumerate(months)}
    day_index = {day: i for i, day in enumerate(days)}

    grid = [[None for _ in days] for _ in months]

    for record in records:
        _, month, day = map(int, record["Date"].split("-"))
        row = month_index[month]
        col = day_index[day]
        grid[row][col] = float(record["Temperature"])

    return grid
