import math


def feature_correlation_matrix(samples):
    if not samples or not samples[0]:
        return []

    n_rows = len(samples)
    n_features = len(samples[0])

    # Feature means
    means = [
        sum(row[j] for row in samples) / n_rows
        for j in range(n_features)
    ]

    # Squared deviations per feature
    variances = [0.0] * n_features
    for row in samples:
        for j in range(n_features):
            d = row[j] - means[j]
            variances[j] += d * d

    corr = [[0.0] * n_features for _ in range(n_features)]

    for i in range(n_features):
        corr[i][i] = 1.0

    for i in range(n_features):
        for j in range(i + 1, n_features):
            covariance = 0.0

            for row in samples:
                covariance += (row[i] - means[i]) * (row[j] - means[j])

            denominator = math.sqrt(variances[i] * variances[j])

            if denominator == 0:
                value = 0.0
            else:
                value = covariance / denominator

            corr[i][j] = value
            corr[j][i] = value

    return corr
