from html.parser import HTMLParser


class _Node:
    __slots__ = ("tag", "children")

    def __init__(self, tag):
        self.tag = tag
        self.children = []


class _TableParser(HTMLParser):
    VOID_ELEMENTS = {
        "area", "base", "br", "col", "embed", "hr", "img", "input",
        "link", "meta", "param", "source", "track", "wbr"
    }

    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.root = _Node(None)
        self.stack = [self.root]

    def handle_starttag(self, tag, attrs):
        tag = tag.lower()

        if tag == "tr":
            self._close_open_row()
        elif tag in ("td", "th"):
            self._close_open_cell()

        node = _Node(tag)
        self.stack[-1].children.append(node)

        if tag not in self.VOID_ELEMENTS:
            self.stack.append(node)

    def handle_endtag(self, tag):
        tag = tag.lower()

        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i].tag == tag:
                del self.stack[i:]
                return

    def handle_data(self, data):
        self.stack[-1].children.append(data)

    def _close_open_row(self):
        table_idx = -1
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i].tag == "table":
                table_idx = i
                break

        tr_idx = -1
        for i in range(len(self.stack) - 1, table_idx, -1):
            if self.stack[i].tag == "tr":
                tr_idx = i
                break

        if tr_idx != -1:
            del self.stack[tr_idx:]

    def _close_open_cell(self):
        tr_idx = -1
        for i in range(len(self.stack) - 1, -1, -1):
            if self.stack[i].tag == "tr":
                tr_idx = i
                break
            if self.stack[i].tag == "table":
                break

        if tr_idx != -1:
            del self.stack[tr_idx + 1:]


def extract_table_rows(html):
    parser = _TableParser()
    parser.feed(html)
    parser.close()

    def iter_tr_nodes(node):
        for child in node.children:
            if isinstance(child, _Node):
                if child.tag == "tr":
                    yield child
                yield from iter_tr_nodes(child)

    def text_content(node):
        parts = []

        def walk(current):
            for child in current.children:
                if isinstance(child, _Node):
                    walk(child)
                else:
                    parts.append(child)

        walk(node)
        return "".join(parts)

    result = []

    for tr in iter_tr_nodes(parser.root):
        cells = []
        for child in tr.children:
            if isinstance(child, _Node) and child.tag == "td":
                cells.append(text_content(child).strip())
        result.append(cells)

    return result
```

